export function createStore() {
  const tasks = [];
  let nextId = 1;
  return {
    add(title) {
      const task = { id: nextId++, title, done: false };
      tasks.push(task);
      return { ...task };
    },
    complete(id) {
      const task = tasks.find((item) => item.id === id);
      if (!task) throw new Error('No task ' + id);
      task.done = true;
      return { ...task };
    },
    list() {
      return tasks.map((task) => ({ ...task }));
    },
  };
}
