// An in-memory task store.
function normalizeTags(tags) {
  if (!Array.isArray(tags)) return [];
  const result = [];
  for (const tag of tags) {
    const normalized = String(tag).trim().toLowerCase();
    if (normalized && !result.includes(normalized)) result.push(normalized);
  }
  return result;
}

export function createStore() {
  const tasks = [];
  let nextId = 1;
  return {
    add(title, options = {}) {
      const task = { id: nextId++, title, done: false, tags: normalizeTags(options.tags) };
      tasks.push(task);
      return { ...task, tags: [...task.tags] };
    },
    complete(id) {
      const task = tasks.find((item) => item.id === id);
      if (!task) throw new Error('No task ' + id);
      task.done = true;
      return { ...task, tags: [...task.tags] };
    },
    list(options = {}) {
      const tag = options.tag === undefined ? undefined : String(options.tag).trim().toLowerCase();
      return tasks
        .filter((task) => tag === undefined || task.tags.includes(tag))
        .map((task) => ({ ...task, tags: [...task.tags] }));
    },
  };
}

export function formatTask(task) {
  const base = (task.done ? '[x]' : '[ ]') + ' ' + task.id + ' ' + task.title;
  const tags = Array.isArray(task.tags) ? task.tags : [];
  return base + tags.map((tag) => ' #' + tag).join('');
}

