import { formatTask } from './format.js';

function parseArgs(args) {
  const positional = [];
  const tags = [];
  for (let i = 0; i < args.length; i++) {
    const arg = args[i];
    if (arg === '--tag') {
      const value = args[i + 1];
      if (value === undefined || value.startsWith('-')) throw new Error('--tag needs a value');
      tags.push(value);
      i++;
    } else if (arg.startsWith('-')) {
      throw new Error('Unknown option: ' + arg);
    } else {
      positional.push(arg);
    }
  }
  return { positional, tags };
}

// Runs one command and returns the lines to print.
export function run(store, argv) {
  const [command, ...rest] = argv;
  if (command === 'add') {
    const { positional, tags } = parseArgs(rest);
    return [formatTask(store.add(positional.join(' '), { tags }))];
  }
  if (command === 'done') return [formatTask(store.complete(Number(rest[0])))];
  if (command === 'list') {
    const { tags } = parseArgs(rest);
    return store.list(tags.length ? { tag: tags[0] } : {}).map(formatTask);
  }
  throw new Error('Unknown command: ' + command);
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { createStore } from '../src/store.js';
import { formatTask } from '../src/format.js';
import { run } from '../src/cli.js';

test('add normalizes tags and keeps first-seen order', () => {
  const store = createStore();
  const task = store.add('Buy milk', { tags: [' Home ', 'ERRAND', 'home', 'errand'] });
  assert.deepEqual(task.tags, ['home', 'errand']);
});

test('every task has a tags array, empty when none were given', () => {
  const store = createStore();
  const task = store.add('Plain task');
  assert.deepEqual(task.tags, []);
  assert.deepEqual(store.list()[0].tags, []);
});

test('list filters by tag case-insensitively and list() returns everything', () => {
  const store = createStore();
  store.add('Buy milk', { tags: ['home'] });
  store.add('Send letter', { tags: ['errand'] });
  store.add('Plain task');

  assert.equal(store.list().length, 3);
  assert.deepEqual(store.list({ tag: 'HOME' }).map((t) => t.title), ['Buy milk']);
  assert.deepEqual(store.list({ tag: ' Errand ' }).map((t) => t.title), ['Send letter']);
  assert.deepEqual(store.list({ tag: 'missing' }), []);
});

test('complete preserves tags', () => {
  const store = createStore();
  const task = store.add('Buy milk', { tags: ['home'] });
  assert.deepEqual(store.complete(task.id).tags, ['home']);
});

test('formatTask appends tags after the title', () => {
  assert.equal(
    formatTask({ id: 1, title: 'Buy milk', done: false, tags: ['home', 'errand'] }),
    '[ ] 1 Buy milk #home #errand',
  );
  assert.equal(formatTask({ id: 2, title: 'Plain', done: true, tags: [] }), '[x] 2 Plain');
  assert.equal(formatTask({ id: 3, title: 'No tags field', done: false }), '[ ] 3 No tags field');
});

test('CLI add accepts repeated --tag and list filters by --tag', () => {
  const store = createStore();
  assert.deepEqual(run(store, ['add', 'Buy', 'milk', '--tag', 'home', '--tag', 'errand']), [
    '[ ] 1 Buy milk #home #errand',
  ]);
  run(store, ['add', 'Plain task']);
  assert.deepEqual(run(store, ['list', '--tag', 'HOME']), ['[ ] 1 Buy milk #home #errand']);
  assert.equal(run(store, ['list']).length, 2);
});

test('CLI rejects unknown options and a valueless --tag', () => {
  const store = createStore();
  assert.throws(() => run(store, ['list', '--x']), { message: 'Unknown option: --x' });
  assert.throws(() => run(store, ['add', 'Buy milk', '--nope']), {
    message: 'Unknown option: --nope',
  });
  assert.throws(() => run(store, ['add', 'Buy milk', '--tag']), {
    message: '--tag needs a value',
  });
  assert.throws(() => run(store, ['list', '--tag', '--x']), { message: '--tag needs a value' });
  assert.equal(store.list().length, 0);
});

